import{_ as c,C as i,o as n,c as l,ak as a,E as o,j as t,a as r}from"./chunks/framework.DxrHb2fb.js";const f=JSON.parse('{"title":"Skeleton 骨架屏","description":"","frontmatter":{},"headers":[],"relativePath":"components/skeleton.md","filePath":"components/skeleton.md","lastUpdated":1790174783000}'),h={name:"components/skeleton.md"};function s(b,e,u,p,m,k){const d=i("XhDemo");return n(),l("div",null,[e[0]||(e[0]=a('<h1 id="skeleton-骨架屏" tabindex="-1">Skeleton 骨架屏 <a class="header-anchor" href="#skeleton-骨架屏" aria-label="Permalink to &quot;Skeleton 骨架屏&quot;">​</a></h1><p>内容尚未到达时，按最终版面占位。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/skeleton" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/skeleton.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/skeleton" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/skeleton" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/skeleton.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>按真实卡片的封面与文字节奏占位</p>',5)),o(d,{src:"skeleton/01-basic"}),e[1]||(e[1]=a('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;skeleton&quot;</code>：<strong><code>root</code></strong> · <strong><code>item</code></strong></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="形状" tabindex="-1">形状 <a class="header-anchor" href="#形状" aria-label="Permalink to &quot;形状&quot;">​</a></h3><p>容器的 shape 是该组的默认形状，单根骨架条自带 shape 时按自己的形状</p>',6)),o(d,{src:"skeleton/02-variant"}),e[2]||(e[2]=t("h3",{id:"加载结束",tabindex:"-1"},[r("加载结束 "),t("a",{class:"header-anchor",href:"#加载结束","aria-label":'Permalink to "加载结束"'},"​")],-1)),e[3]||(e[3]=t("p",null,"loading 期间容器报告 aria-busy，切换为 false 后整块收起，位置让给真实内容",-1)),o(d,{src:"skeleton/03-loading"}),e[4]||(e[4]=t("h3",{id:"动效",tabindex:"-1"},[r("动效 "),t("a",{class:"header-anchor",href:"#动效","aria-label":'Permalink to "动效"'},"​")],-1)),e[5]||(e[5]=t("p",null,"在微光、呼吸和静止三档之间选择",-1)),o(d,{src:"skeleton/04-animation"}),e[6]||(e[6]=a('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>首屏或整块区域的加载，且版面结构可预测。</li><li>加载时间通常在几百毫秒到几秒之间。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>加载极快时，骨架闪烁比直接出现更差。</li><li>版面完全不可预测时，使用<a href="./spinner">加载指示器</a>。</li><li>一次动作的等待（提交中）使用按钮的载入态。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li><code>loading</code> 为假时替换为真实内容。</li><li><code>shape</code> 决定骨块的形状（文本行、圆形、矩形）。</li><li><code>animation</code> 在微光、呼吸和静止三档之间切换。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>按最终版面用<a href="./grid">栅格</a>或<a href="./flex">弹性布局</a>排列骨块。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>骨架的形状与真实内容对应：行数、宽度、圆角都要接近，否则内容到达时整块跳动。</li><li>不做得比真实内容更复杂。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>用一块巨大的灰色矩形代替所有内容。</li><li>加载失败后骨架持续闪烁。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-skeleton&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhSkeletonItem</code> <code>XhSkeletonRoot</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/skeleton.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>animation</code></td><td><code>SkeletonAnimation</code></td><td></td><td>动效档，默认 &#39;shimmer&#39;；默认档不输出 data-animation。</td></tr><tr><td><code>loading</code></td><td><code>boolean</code></td><td></td><td>是否还在加载，默认 true。</td></tr><tr><td><code>shape</code></td><td><code>SkeletonShape</code></td><td></td><td>容器内骨架条的默认形状，默认 &#39;text&#39;。</td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to &quot;React 适配器 props&quot;">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhSkeletonItem</code></td><td><code>shape</code></td><td><code>SkeletonShape</code></td><td></td><td>该根的形状，覆盖容器提供的默认值。</td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;loading&#39; | &#39;loaded&#39;</td></tr></tbody></table><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>loading</code></td><td><code>boolean</code></td><td>当前是否处于加载态。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(item?: SkeletonItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-busy</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>item</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39; | undefined</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/skeleton.css</code> 使用 <code>[data-scope=&quot;skeleton&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 与 <code>xihan.motion</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-animation</code></td><td>props.animation</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;loading&#39; | &#39;loaded&#39;</td></tr><tr><td><code>item</code></td><td><code>data-shape</code></td><td>item.shape</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-skeleton-bg</code></td><td><code>item</code></td><td><code>background-color</code></td><td><code>default</code></td><td><code>--xh-bg-subtle</code></td><td>skeleton 的 item 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-skeleton-circle-radius</code></td><td><code>item</code></td><td><code>border-radius</code></td><td><code>shape=circle</code></td><td><code>--xh-shape-circle</code></td><td>skeleton 的 item 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-skeleton-circle-size</code></td><td><code>item</code></td><td><code>inline-size</code></td><td><code>shape=circle</code></td><td><code>--xh-control-h-lg</code></td><td>skeleton 的 item 部件 inline-size 覆盖槽。</td></tr><tr><td><code>--xh-skeleton-duration</code></td><td><code>item</code></td><td><code>animation</code></td><td><code>default</code></td><td><code>--xh-shimmer-duration</code></td><td>skeleton 的 item 部件 animation 覆盖槽。</td></tr><tr><td><code>--xh-skeleton-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-3</code></td><td>skeleton 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-skeleton-pulse-duration</code></td><td><code>item</code><br><code>root</code></td><td><code>animation</code></td><td><code>animation=pulse</code></td><td><code>--xh-shimmer-duration</code></td><td>skeleton 的 item、root 部件 animation 覆盖槽。</td></tr><tr><td><code>--xh-skeleton-radius</code></td><td><code>item</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>skeleton 的 item 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-skeleton-rect-block-size</code></td><td><code>item</code></td><td><code>min-block-size</code></td><td><code>shape=rect</code></td><td><code>--xh-control-h-lg</code></td><td>skeleton 的 item 部件 min-block-size 覆盖槽。</td></tr><tr><td><code>--xh-skeleton-rect-radius</code></td><td><code>item</code></td><td><code>border-radius</code></td><td><code>shape=rect</code></td><td><code>--xh-shape-surface</code></td><td>skeleton 的 item 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-skeleton-sheen</code></td><td><code>item</code></td><td><code>background-image</code></td><td><code>default</code></td><td><code>--xh-bg-surface-raised</code></td><td>skeleton 的 item 部件 background-image 覆盖槽。</td></tr><tr><td><code>--xh-skeleton-text-block-size</code></td><td><code>item</code></td><td><code>block-size</code></td><td><code>shape=text</code></td><td><code>--xh-text-caption-size</code></td><td>skeleton 的 item 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-skeleton-text-radius</code></td><td><code>item</code></td><td><code>border-radius</code></td><td><code>shape=text</code></td><td><code>--xh-shape-pill</code></td><td>skeleton 的 item 部件 border-radius 覆盖槽。</td></tr></tbody></table><h3 id="动效-1" tabindex="-1">动效 <a class="header-anchor" href="#动效-1" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>关键帧 <code>xh-skeleton-pulse</code> · <code>xh-skeleton-shimmer</code> 随皮肤自带，不引用别处文件里的名字。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p><code>prefers-reduced-motion: reduce</code> 下本组件另有降级规则。</p>',47))])}const q=c(h,[["render",s]]);export{f as __pageData,q as default};
